CREATE OR REPLACE FUNCTION app_private.log_application_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_provider text;
  v_event text;
  v_document_result text;
begin
  select app_private.application_provider_target(l.source_id,l.raw,l.canonical_url)
    into v_provider
  from public.listings l
  where l.id=new.listing_id;

  if tg_op='INSERT' then
    v_event := 'queued';
  elsif new.status is distinct from old.status then
    v_event := 'status_changed';
  elsif new.wait_reason is distinct from old.wait_reason then
    v_event := 'wait_changed';
  else
    return new;
  end if;

  v_document_result := case
    when new.provider_state->>'document_result' in (
      'native_uploaded','link_included','not_provided','not_supported','transfer_failed'
    ) then new.provider_state->>'document_result'
    else null
  end;

  insert into public.application_events(
    application_id,user_id,provider,event_type,status,attempt,reason,document_result,metadata
  )
  values(
    new.id,new.user_id,v_provider,v_event,new.status,new.attempts,
    coalesce(new.wait_reason,new.last_error),v_document_result,
    jsonb_build_object('source_id',new.source_id)
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app_private.maintenance_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r record;
  removed integer;
  result jsonb := '{}';
begin
  delete from public.crawl_runs
  where ctid in (
    select ctid
    from public.crawl_runs
    where success=true and finished_at<now()-interval '3 days'
    union all
    select ctid
    from public.crawl_runs
    where success=false and finished_at<now()-interval '30 days'
    limit 5000
  );
  get diagnostics removed = row_count;
  result := jsonb_build_object('crawl_runs_deleted',removed);

  for r in
    select * from (values
      ('source_jobs_deleted','public.source_jobs',
       $$((status='done' and finished_at<now()-interval '1 day')
          or (status='dead' and finished_at<now()-interval '7 days'))$$),
      ('queue_archive_deleted','pgmq.a_source_jobs',
       $$archived_at<now()-interval '2 days'$$),
      ('delivery_events_deleted','public.delivery_events',
       $$status in ('sent','skipped') and created_at<now()-interval '90 days'$$),
      ('shadow_runs_deleted','app_private.source_shadow_runs',
       $$checked_at<now()-interval '14 days'$$),
      ('telegram_effects_deleted','app_private.telegram_effects',
       $$update_id in (
         select telegram_update_id
         from public.bot_events
         where created_at<now()-interval '30 days'
           and processing_status='done'
       )$$),
      ('cron_runs_deleted','cron.job_run_details',
       $$((status='succeeded' and end_time<now()-interval '1 day')
          or (status='failed' and end_time<now()-interval '30 days'))$$)
    ) as rules(key,relation,predicate)
  loop
    execute format(
      'delete from %s where ctid in (select ctid from %s where %s limit 5000)',
      r.relation,r.relation,r.predicate
    );
    get diagnostics removed = row_count;
    result := result || jsonb_build_object(r.key,removed);
  end loop;

  result := result || jsonb_build_object(
    'performance_snapshot_created',
    app_private.capture_performance_snapshot()
  );
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.matches_property_filters(p search_profiles, l listings)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  c jsonb;
  v_category text;
  v_price numeric;
  v_rooms numeric;
  v_area numeric;
  v_haystack text;
  v_location_ok boolean:=false;
begin
  if cardinality(p.property_types)<>1
     or p.property_types[1] not in ('Wohnung','Haus','WG','Tauschwohnung') then
    return false;
  end if;

  -- Business rule: every Baugenossenschaft offer belongs to the Wohnung filter.
  if exists (
    select 1
    from public.sources s
    where s.id=l.source_id
      and s.source_type='Baugenossenschaft'
  ) then
    v_category:='Wohnung';
  else
    c:=app_private.classify_listing_category(
      l.source_id,l.property_type,l.property_kind,l.offer_mode,l.title,l.raw
    );
    v_category:=c->>'category';
  end if;

  if v_category is null or v_category<>p.property_types[1] then
    return false;
  end if;

  if p.max_warm_rent is not null then
    v_price:=nullif(l.warm_rent,0);

    if v_price is not null and v_price>p.max_warm_rent then
      return false;
    end if;

    if v_price is null
       and coalesce(p.require_known_warm_rent,false)=false
       and coalesce(nullif(l.cold_rent,0),0)>p.max_warm_rent then
      return false;
    end if;
  end if;

  if coalesce(p.require_known_warm_rent,false) and coalesce(l.warm_rent,0)<=0 then
    return false;
  end if;

  if p.max_deposit is not null and (l.deposit is null or l.deposit>p.max_deposit) then
    return false;
  end if;

  if p.wbs_only and l.wbs_required is distinct from true then
    return false;
  end if;

  if p.furnished_preference='yes' and l.furnished is distinct from true then
    return false;
  elsif p.furnished_preference='no' and l.furnished is distinct from false then
    return false;
  end if;

  v_rooms:=nullif(l.rooms,0);
  v_area:=nullif(l.area_sqm,0);

  if coalesce(p.min_rooms,0)>0
     and v_rooms is not null
     and v_rooms<p.min_rooms then
    return false;
  end if;

  if coalesce(p.min_area_sqm,0)>0
     and v_area is not null
     and v_area<p.min_area_sqm then
    return false;
  end if;

  v_haystack:=lower(concat_ws(' ',l.district,l.address,l.title,l.raw::text));

  v_location_ok :=
    p.location_mode='all_hamburg'
    or (p.location_mode='boroughs' and coalesce(cardinality(p.boroughs),0)>=7)
    or (
      p.location_mode='neighborhoods'
      and exists(
        select 1 from unnest(p.neighborhoods) n
        where v_haystack like '%'||lower(n)||'%'
      )
    )
    or (
      p.location_mode='boroughs'
      and exists(
        select 1
        from public.hamburg_neighborhoods hn
        join public.hamburg_boroughs hb on hb.id=hn.borough_id
        where hb.name=any(p.boroughs)
          and v_haystack like '%'||lower(hn.name)||'%'
      )
    )
    or (
      coalesce(cardinality(p.districts),0)>0
      and (
        'Ganz Hamburg'=any(p.districts)
        or exists(
          select 1 from unnest(p.districts) d
          where v_haystack like '%'||lower(d)||'%'
        )
      )
    );

  return coalesce(v_location_ok,false);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.normalize_explicit_listing_facts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m text[]; v_rooms numeric; v_addr_plz text;
begin
  m:=regexp_match(coalesce(new.title,''),'(?i)([0-9]+(?:[.,][0-9]+)?)\s*[-– ]\s*Zimmer');
  if m is not null then
    begin v_rooms:=replace(m[1],',','.')::numeric; exception when others then v_rooms:=null; end;
    if v_rooms between 0.5 and 20 and (new.rooms is null or abs(new.rooms-v_rooms)>0.25) then
      new.rooms:=v_rooms;
      new.enrichment_evidence:=jsonb_set(coalesce(new.enrichment_evidence,'{}'::jsonb),'{rooms}',jsonb_build_object('value',v_rooms,'source','title:explicit_rooms','confidence',0.995),true);
      new.field_conflicts:=coalesce(new.field_conflicts,'{}'::jsonb)-'rooms';
    end if;
  end if;
  if new.address is not null then
    new.address:=regexp_replace(new.address,'(?i)^\s*(?:Kaltmiete|Warmmiete|Gesamtmiete|Miete)\s+','','');
    new.address:=regexp_replace(new.address,'\s+',' ','g');
    v_addr_plz:=substring(new.address from '(2[0-9]{4})');
    if new.address ~* '(Andere Anzeigen des Anbieters|Alle Anzeigen dieses Anbieters|Weitere Anzeigen|Ähnliche Anzeigen|Anbieter kontaktieren|Immobilienangebote)' 
       or (new.postal_code is not null and v_addr_plz is not null and v_addr_plz<>new.postal_code) then
      new.address:=null;
    end if;
  end if;
  return new;
end;
$function$

