CREATE OR REPLACE FUNCTION app_private.normalize_listing_image_url()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.source_id=2 and new.image_url is not null and new.image_url ~ '^https://img[.]kleinanzeigen[.]de/' then
    new.image_url:=regexp_replace(new.image_url,'[.]AUTO([&#?]|$)','.JPG\1','i');
  elsif new.source_id=3 and new.image_url is not null and new.image_url ~ '^https://mms[.]immowelt[.]de/' then
    if new.image_url ~ '([?&])h=50([&#]|$)' and new.image_url !~ '([?&])w=' then
      new.image_url:=regexp_replace(new.image_url,'([?&])h=50([&#]|$)','\1w=525&h=394\2','i');
    end if;
    new.resolved_image_url:=new.image_url;
    new.image_status:='direct';
    new.image_source:='immowelt_mms';
    new.image_error:=null;
    new.image_last_checked_at:=now();
  elsif new.source_id=15 and new.image_url is not null then
    if new.image_url ~ '^https://[^/]+[.]supabase[.]co/srv/obs/' then
      new.image_url:=regexp_replace(new.image_url,'^https://[^/]+[.]supabase[.]co/srv/obs/','https://www.immobilien.de/srv/obs/');
    end if;
    if new.image_url ~ '^https://www[.]immobilien[.]de/srv/obs/' then
      new.resolved_image_url:=new.image_url;
      new.image_status:='direct';
      new.image_source:='immobilien_de_cdn';
      new.image_error:=null;
      new.image_last_checked_at:=now();
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.normalize_listing_presentation_facts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  txt text := coalesce(new.raw->>'text','') || ' ' || coalesce(new.raw->>'snippet','') || ' ' || coalesce(new.raw->>'alt','') || ' ' || coalesce(new.title,'');
  m text[];
  candidate text;
begin
  if nullif(btrim(new.address),'') is null then
    candidate := coalesce(
      nullif(btrim(new.raw#>>'{address,streetAddress}'),''),
      nullif(btrim(new.raw#>>'{address,street}'),''),
      nullif(btrim(new.raw->>'streetAddress'),''),
      nullif(btrim(new.raw->>'street'),'')
    );
    if candidate is not null then
      candidate := btrim(candidate || case when coalesce(new.raw#>>'{address,houseNumber}',new.raw->>'houseNumber') is not null then ' ' || coalesce(new.raw#>>'{address,houseNumber}',new.raw->>'houseNumber') else '' end);
      new.address := candidate;
    else
      m := regexp_match(txt, '(?i)([A-ZÄÖÜ][A-Za-zÄÖÜäöüß .''-]{1,60}(?:straße|strasse|str\.|weg|allee|ring|platz|chaussee|damm|kamp|stieg|ufer|twiete|gasse)\s+[0-9]{1,4}[a-zA-Z]?(?:\s*[-/]\s*[0-9]{1,4}[a-zA-Z]?)?)');
      if m is not null then new.address := btrim(m[1]); end if;
    end if;
  end if;

  if nullif(btrim(new.district),'') is null then
    new.district := coalesce(nullif(btrim(new.raw#>>'{address,district}'),''),nullif(btrim(new.raw->>'district'),''),nullif(btrim(new.raw#>>'{entry,address,quarter}'),''));
  end if;
  if nullif(btrim(new.postal_code),'') is null then
    new.postal_code := coalesce(nullif(btrim(new.raw#>>'{address,postalCode}'),''),nullif(btrim(new.raw#>>'{address,zipCode}'),''),nullif(btrim(new.raw->>'postalCode'),''),nullif(btrim(new.raw->>'zipCode'),''),substring(txt from '\m(2[0-9]{4})\M'));
  end if;

  if new.image_url like 'https://www.grandcityproperty.de/grandcityproperty.de/%' then
    new.image_url := regexp_replace(new.image_url, '^https://www[.]grandcityproperty[.]de/grandcityproperty[.]de/', 'https://www.grandcityproperty.de/');
  end if;

  if new.image_url ~ '^https://mms[.]immowelt[.]de/' then
    if new.image_url ~ '([?&])h=50([&#]|$)' and new.image_url !~ '([?&])w=' then
      new.image_url := regexp_replace(new.image_url,'([?&])h=50([&#]|$)','\1w=525&h=394\2','i');
    end if;
    new.resolved_image_url := new.image_url;
    new.image_status := 'direct';
    new.image_source := 'immowelt_mms';
    new.image_error := null;
    new.image_last_checked_at := now();
  elsif new.image_url ~* '^https://.*\.(?:jpe?g|png|webp)(?:[?&#]|$)' then
    new.resolved_image_url := new.image_url;
    new.image_status := 'direct';
    new.image_source := coalesce(new.image_source,'source_direct');
    new.image_error := null;
    new.image_last_checked_at := coalesce(new.image_last_checked_at,now());
  end if;

  if new.source_id=8 and new.canonical_url ~* '/wohnungssuche/(leipzig|dresden|celle|halle-saale-|chemnitz|delmenhorst|osterwieck)/' then
    new.quality_status := 'rejected';
    new.is_active := false;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.notify_immomio_connection_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_chat bigint; v_markup jsonb;
begin
  if new.provider <> 'immomio' then return new; end if;
  if tg_op='UPDATE' and old.status is not distinct from new.status then return new; end if;
  if new.status <> 'connected' then return new; end if;
  select chat_id into v_chat from public.bot_users where id=new.user_id;
  if v_chat is null then return new; end if;
  v_markup := jsonb_build_object('inline_keyboard',jsonb_build_array(
    jsonb_build_array(jsonb_build_object('text','🔐 Immomio','callback_data','platforms:immomio')),
    jsonb_build_array(jsonb_build_object('text','⚡ Automatische Bewerbung','callback_data','platforms'))
  ));
  perform app_private.telegram_api_call('sendMessage',jsonb_build_object(
    'chat_id',v_chat,'parse_mode','HTML','disable_web_page_preview',true,
    'text','✅ <b>Immomio verbunden</b>\n\nDie Anmeldung ist verschlüsselt gespeichert.',
    'reply_markup',v_markup
  ));
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app_private.parse_eur(raw_value text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare s text := trim(raw_value);
begin
  s := regexp_replace(s, '[^0-9,.-]', '', 'g');
  if s = '' then return null; end if;
  if position(',' in s) > 0 then
    s := replace(replace(s, '.', ''), ',', '.');
  elsif s ~ '^[0-9]{1,3}\.[0-9]{3}$' then
    s := replace(s, '.', '');
  end if;
  return s::numeric;
exception when others then return null;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.prepare_listing_fast_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  -- Enrichment stays as data-quality telemetry only; it is not a delivery gate.
  new.enrichment_status := 'done';
  new.enrichment_delivery_eligible := true;
  new.enrichment_error := null;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.preserve_connected_kleinanzeigen_during_relogin()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.provider = 'kleinanzeigen'
     and old.status = 'connected'
     and new.status = 'pending'
     and old.credential_ciphertext is not null
     and old.credential_iv is not null then
    new.status := 'connected';
    new.last_error := old.last_error;
    new.last_verified_at := old.last_verified_at;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.preserve_enriched_listing_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.cold_rent is null and old.cold_rent is not null then new.cold_rent:=old.cold_rent; end if;
  if new.warm_rent is null and old.warm_rent is not null and not (
    new.source_id=16 and (
      coalesce(old.enrichment_evidence->'additional_costs'->>'source','')='detail:text'
      or coalesce(old.enrichment_evidence->'heating_costs'->>'source','')='detail:text'
    )
  ) then
    new.warm_rent:=old.warm_rent;
    new.warm_rent_is_calculated:=old.warm_rent_is_calculated;
  end if;
  if new.heating_costs is null and old.heating_costs is not null and not (
    new.source_id=16 and coalesce(old.enrichment_evidence->'heating_costs'->>'source','')='detail:text'
  ) then new.heating_costs:=old.heating_costs; end if;
  if new.additional_costs is null and old.additional_costs is not null and not (
    new.source_id=16 and coalesce(old.enrichment_evidence->'additional_costs'->>'source','')='detail:text'
  ) then new.additional_costs:=old.additional_costs; end if;
  if new.operating_costs is null and old.operating_costs is not null then new.operating_costs:=old.operating_costs; end if;
  if new.deposit is null and old.deposit is not null then new.deposit:=old.deposit; end if;
  if nullif(new.deposit_text,'') is null and nullif(old.deposit_text,'') is not null then new.deposit_text:=old.deposit_text; end if;
  if new.area_sqm is null and old.area_sqm is not null then new.area_sqm:=old.area_sqm; end if;
  if new.rooms is null and old.rooms is not null then new.rooms:=old.rooms; end if;
  if nullif(new.image_url,'') is null and nullif(old.image_url,'') is not null then new.image_url:=old.image_url; end if;
  if nullif(new.resolved_image_url,'') is null and nullif(old.resolved_image_url,'') is not null then new.resolved_image_url:=old.resolved_image_url; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.process_partial_coop_provider_checks()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r record;
  b record;
  v_block text;
  v_plain text;
  v_external_id text;
  v_mirror public.listings%rowtype;
  v_source public.sources%rowtype;
  v_key text;
  v_exists boolean;
  v_matched integer;
  v_inserted integer;
  v_processed integer := 0;
  v_retry_request_id bigint;
begin
  for r in
    select q.id,q.source_id,q.query_kind,q.request_id,q.requested_at,q.error as request_state,
           c.needle,c.query_url,h.status_code,h.timed_out,h.error_msg,h.content
    from app_private.coop_provider_index_requests q
    join app_private.coop_provider_query_config() c
      on c.source_id=q.source_id and c.query_kind=q.query_kind
    join net._http_response h on h.id=q.request_id
    where q.processed_at is null
    order by q.requested_at
    limit 40
  loop
    v_matched := 0;
    v_inserted := 0;

    if coalesce(r.timed_out,false) or r.error_msg is not null then
      if coalesce(r.request_state,'') <> 'retrying_once' then
        select net.http_get(url:=r.query_url,timeout_milliseconds:=15000)
          into v_retry_request_id;
        update app_private.coop_provider_index_requests
        set request_id=v_retry_request_id,
            requested_at=now(),
            status_code=r.status_code,
            error='retrying_once'
        where id=r.id;
        continue;
      end if;

      update app_private.coop_provider_index_requests
      set processed_at=now(),
          status_code=r.status_code,
          error=left(coalesce(r.error_msg,'transport failure'),1000)
      where id=r.id;

      v_processed := v_processed+1;
      continue;
    end if;

    if r.status_code is distinct from 200 then
      update app_private.coop_provider_index_requests
      set processed_at=now(),
          status_code=r.status_code,
          error=left('HTTP '||coalesce(r.status_code::text,'unknown'),1000)
      where id=r.id;

      v_processed := v_processed+1;
      continue;
    end if;

    select * into v_source
    from public.sources
    where id=r.source_id;

    if not found then
      update app_private.coop_provider_index_requests
      set processed_at=now(),
          status_code=r.status_code,
          error='source missing'
      where id=r.id;

      v_processed := v_processed+1;
      continue;
    end if;

    update public.sources
    set last_success_at=now(),
        updated_at=now()
    where id=r.source_id;

    for b in
      select x[1] as block
      from regexp_matches(r.content,'(<li><div class="dd algo[\s\S]*?</li>)','gi') x
    loop
      v_block := lower(b.block);
      v_plain := lower(regexp_replace(b.block,'<[^>]+>',' ','g'));

      if v_block not like '%'||r.needle||'%'
         or v_plain not like '%hamburg%'
         or v_plain !~ '(wohnung|apartment|appartement|mietwohnung)'
         or v_plain !~ '(miete|vermiet|mietwohnung)'
      then
        continue;
      end if;

      v_external_id := null;
      v_mirror := null;

      if r.query_kind='immoscout' then
        v_external_id := coalesce(
          (regexp_match(v_block,'immobilienscout24\.de%2fexpose%2f([0-9]+)'))[1],
          (regexp_match(v_block,'immobilienscout24\.de/expose/([0-9]+)'))[1]
        );

        if v_external_id is not null then
          select l.* into v_mirror
          from public.listings l
          where l.source_id=1
            and l.is_active=true
            and l.quality_status<>'rejected'
            and l.canonical_url ~ ('/expose/'||v_external_id||'([/?#]|$)')
          order by l.last_seen_at desc
          limit 1;
        end if;
      else
        v_external_id := coalesce(
          (regexp_match(v_block,'immowelt\.de%2fexpose%2f([a-f0-9-]{36})'))[1],
          (regexp_match(v_block,'immowelt\.de/expose/([a-f0-9-]{36})'))[1]
        );

        if v_external_id is not null then
          select l.* into v_mirror
          from public.listings l
          where l.source_id=3
            and l.is_active=true
            and l.quality_status<>'rejected'
            and lower(l.canonical_url) ~ ('/expose/'||v_external_id||'([/?#]|$)')
          order by l.last_seen_at desc
          limit 1;
        end if;
      end if;

      if v_external_id is null or v_mirror.id is null then
        continue;
      end if;

      if v_mirror.last_seen_at < now()-interval '2 hours' then
        continue;
      end if;

      v_matched := v_matched+1;
      v_key := 'provider-index:'||r.query_kind||':'||v_external_id;

      select exists(
        select 1
        from public.listings
        where source_id=r.source_id
          and source_listing_key=v_key
      ) into v_exists;

      if not v_exists then
        insert into public.listings(
          source_id,source_listing_key,external_id,canonical_url,title,address,district,postal_code,city,
          warm_rent,cold_rent,rooms,area_sqm,available_from,property_type,furnished,wbs_required,image_url,cross_source_hash,raw,
          first_seen_at,last_seen_at,is_active,heating_costs,additional_costs,operating_costs,deposit,deposit_text,
          resolved_image_url,image_source,image_status,image_last_checked_at,image_error,
          enrichment_status,enrichment_checked_at,enrichment_error,enrichment_evidence,field_conflicts,enrichment_delivery_eligible,
          quality_status,quality_reason,warm_rent_is_calculated,fresh_delivery_eligible,latitude,longitude
        ) values (
          r.source_id,v_key,v_external_id,v_mirror.canonical_url,v_mirror.title,v_mirror.address,v_mirror.district,v_mirror.postal_code,v_mirror.city,
          v_mirror.warm_rent,v_mirror.cold_rent,v_mirror.rooms,v_mirror.area_sqm,v_mirror.available_from,v_mirror.property_type,v_mirror.furnished,v_mirror.wbs_required,v_mirror.image_url,v_mirror.cross_source_hash,
          coalesce(v_mirror.raw,'{}'::jsonb)||jsonb_build_object('provider_index',jsonb_build_object('verified',true,'query_kind',r.query_kind,'mirror_source_id',v_mirror.source_id,'mirror_listing_id',v_mirror.id,'verified_at',now())),
          now(),now(),true,v_mirror.heating_costs,v_mirror.additional_costs,v_mirror.operating_costs,v_mirror.deposit,v_mirror.deposit_text,
          v_mirror.resolved_image_url,v_mirror.image_source,v_mirror.image_status,v_mirror.image_last_checked_at,v_mirror.image_error,
          v_mirror.enrichment_status,v_mirror.enrichment_checked_at,v_mirror.enrichment_error,v_mirror.enrichment_evidence,v_mirror.field_conflicts,v_mirror.enrichment_delivery_eligible,
          v_mirror.quality_status,v_mirror.quality_reason,v_mirror.warm_rent_is_calculated,v_mirror.fresh_delivery_eligible,v_mirror.latitude,v_mirror.longitude
        );
        v_inserted := v_inserted+1;
      else
        update public.listings
        set last_seen_at=now(),
            is_active=true
        where source_id=r.source_id
          and source_listing_key=v_key;
      end if;
    end loop;

    update app_private.coop_provider_index_requests
    set processed_at=now(),
        status_code=r.status_code,
        matched_count=v_matched,
        inserted_count=v_inserted,
        error=null
    where id=r.id;

    update public.listings p
    set is_active=false
    where p.source_id=r.source_id
      and p.is_active=true
      and p.raw ? 'provider_index'
      and not exists (
        select 1
        from public.listings m
        where m.id=(p.raw->'provider_index'->>'mirror_listing_id')::uuid
          and m.is_active=true
          and m.last_seen_at>=now()-interval '2 hours'
      );

    v_processed := v_processed+1;
  end loop;

  return v_processed;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.queue_listing_delivery_v3()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_group uuid;
  v_primary boolean;
  v_source_ready boolean;
  v_haystack text := lower(concat_ws(' ',new.property_type,new.title,new.district,new.address,new.raw::text));
begin
  if not coalesce(new.is_active,false) or coalesce(new.quality_status,'unchecked')='rejected' then
    return new;
  end if;

  if v_haystack ~ '(^|[[:space:]])(ich|wir)[[:space:]]+suche(n)?[[:space:]].{0,40}(wohnung|apartment|wg-zimmer|zimmer|haus)'
     or v_haystack ~ '[[:space:]]sucht[[:space:]]+(dringend[[:space:]]+)?(eine[nr]?[[:space:]]+)?(wohnung|apartment|wg-zimmer|zimmer|haus)'
     or v_haystack ~ '^[[:space:]]*(wohnung|apartment|wg-zimmer|zimmer|haus)[[:space:]]+gesucht'
  then
    return new;
  end if;

  select (s.enabled and s.runtime_mode='live' and s.delivery_mode='live')
    into v_source_ready
  from public.sources s
  where s.id=new.source_id;

  if not coalesce(v_source_ready,false) then
    perform app_private.assign_listing_dedupe(new.id);
    return new;
  end if;

  v_group := app_private.assign_listing_dedupe(new.id);

  select l.is_primary_listing into v_primary
  from public.listings l
  where l.id=new.id;

  if not coalesce(v_primary,false) or v_group is null then
    return new;
  end if;

  if not app_private.delivery_newness_qualified(new.id,statement_timestamp()) then
    return new;
  end if;

  insert into public.delivery_events(
    profile_id,listing_id,dedupe_key,status,delivery_format,
    recipient_user_id,next_retry_at,channel
  )
  select
    p.id,
    new.id,
    'group:'||v_group::text,
    case when owner_user.telegram_user_id is not null and owner_user.chat_id is not null
      then 'pending' else 'available' end,
    case when owner_user.telegram_user_id is not null and owner_user.chat_id is not null
      then 'photo_card' else 'web_match' end,
    p.user_id,
    null,
    case when owner_user.telegram_user_id is not null and owner_user.chat_id is not null
      then 'telegram' else 'web' end
  from public.search_profiles p
  join public.bot_users owner_user
    on owner_user.id=p.user_id
   and owner_user.is_active=true
  where p.is_active=true
    and (p.profile_slot=1 or app_private.user_is_premium(p.user_id))
    and app_private.matches_property_filters(p,new)
  on conflict do nothing;

  return new;
end
$function$

