CREATE OR REPLACE FUNCTION app_private.retry_telegram_updates()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record;v_count integer:=0;
begin
 for r in select payload from public.bot_events
 where processing_attempt<5 and ((processing_status in ('pending','failed') and coalesce(processing_at,created_at)<now()-interval '1 minute') or (processing_status='processing' and processing_at<now()-interval '10 minutes'))
 order by telegram_update_id limit 10
 loop
 perform net.http_post(url:='https://dpmohkrwdlicexwcrqfy.supabase.co/functions/v1/telegram-gateway',headers:=jsonb_build_object('Content-Type','application/json','x-telegram-bot-api-secret-token',public.get_bot_secret('telegram_webhook_secret')),body:=r.payload,timeout_milliseconds:=55000);v_count:=v_count+1;
 end loop;
 for r in select id from app_private.ui_action_jobs where attempt<3 and ((status='pending' and created_at<now()-interval '1 minute') or (status='processing' and lease_until<now())) order by created_at limit 5 loop
 update app_private.ui_action_jobs set status='pending' where id=r.id;
 perform public.dispatch_ui_action(r.id);
 end loop;
 update app_private.ui_action_jobs set status='failed',finished_at=now(),error='recovery_exhausted',lease_until=null where status='processing' and attempt>=3 and lease_until<now();
 delete from app_private.ui_action_jobs where status in ('done','failed') and finished_at<now()-interval '7 days';
 update public.bot_users set application_ui_state='{}' where application_ui_state<>'{}'::jsonb and coalesce(application_ui_state->>'updated_at','')<to_char(now()-interval '1 day','YYYY-MM-DD"T"HH24:MI:SS');
 return v_count;
end $function$

CREATE OR REPLACE FUNCTION app_private.retry_transient_dead_source_jobs(p_limit integer DEFAULT 1, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_msg_id bigint;
  v_limit integer := greatest(1,least(coalesce(p_limit,1),3));
  v_seen integer := 0;
  v_requeued integer := 0;
  v_jobs jsonb := '[]'::jsonb;
begin
  if not pg_try_advisory_xact_lock(hashtextextended('source-dead-letter-retry',0)) then
    return jsonb_build_object('ok',false,'reason','retry_run_already_active','dryRun',coalesce(p_dry_run,true),'eligibleCount',0,'requeuedCount',0,'jobs','[]'::jsonb);
  end if;

  for r in
    select j.id,j.source_id,s.name as source_name,j.attempts,j.updated_at,j.error_message,
      'transient'::text as error_class
    from public.source_jobs j
    join public.sources s on s.id=j.source_id
    where j.status='dead'
      and j.attempts < 3
      and j.updated_at >= now()-interval '24 hours'
      and j.updated_at <= now()-make_interval(mins => 5 * power(2,greatest(j.attempts-1,0))::integer)
      and coalesce(j.error_message,'') ~* '(signal timed out|timed out|timeout|http 429|http 5[0-9]{2}|connection error|connect error|no route to host|service unavailable|bad gateway|connection reset|fetch failed|network error|econn)'
      and coalesce(j.error_message,'') !~* '(lock timeout|deadlock|canceling statement|query canceled|syntax error|permission denied)'
      and s.enabled=true
      and s.runtime_mode='live'
      and s.delivery_mode='live'
      and coalesce(s.consecutive_failures,0)<3
      and (s.last_success_at is null or s.last_success_at<=j.updated_at)
      and not exists (
        select 1 from public.source_jobs active_job
        where active_job.source_id=j.source_id
          and active_job.id<>j.id
          and (active_job.status in ('enqueued','processing','retry')
            or (active_job.status='done' and active_job.updated_at>j.updated_at))
      )
      and not exists (
        select 1 from public.source_jobs newer
        where newer.source_id=j.source_id and newer.id<>j.id
          and newer.status='dead' and newer.updated_at>j.updated_at
      )
    order by j.updated_at asc,j.attempts asc
    limit v_limit
    for update of j skip locked
  loop
    v_seen := v_seen+1;
    if coalesce(p_dry_run,true) then
      v_jobs := v_jobs || jsonb_build_array(jsonb_build_object(
        'jobId',r.id,'sourceId',r.source_id,'source',r.source_name,
        'attempts',r.attempts,'errorClass',r.error_class,'updatedAt',r.updated_at,
        'action','would_requeue'
      ));
      continue;
    end if;

    select x into v_msg_id
    from pgmq.send('source_jobs',jsonb_build_object(
      'job_id',r.id,'source_id',r.source_id,'worker','source-worker'
    )) as x
    limit 1;

    update public.source_jobs
    set queue_msg_id=v_msg_id,status='enqueued',worker='source-worker',
        enqueued_at=now(),started_at=null,finished_at=null,updated_at=now()
    where id=r.id and status='dead' and attempts=r.attempts;

    if found then
      v_requeued := v_requeued+1;
      v_jobs := v_jobs || jsonb_build_array(jsonb_build_object(
        'jobId',r.id,'sourceId',r.source_id,'source',r.source_name,
        'attempts',r.attempts,'errorClass',r.error_class,'updatedAt',r.updated_at,
        'queueMessageId',v_msg_id,'action','requeued'
      ));
    else
      perform pgmq.archive('source_jobs',v_msg_id);
      v_jobs := v_jobs || jsonb_build_array(jsonb_build_object(
        'jobId',r.id,'sourceId',r.source_id,'source',r.source_name,
        'attempts',r.attempts,'action','skipped_concurrent_state_change'
      ));
    end if;
  end loop;

  return jsonb_build_object('ok',true,'dryRun',coalesce(p_dry_run,true),
    'eligibleCount',v_seen,'requeuedCount',v_requeued,'limit',v_limit,'jobs',v_jobs);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.save_search_profile_values(p_user uuid, p_values jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  u public.bot_users%rowtype;
  v public.search_profiles%rowtype;
  v_id uuid;
  slot integer;
  types text[];
  v_type text;
  v_min_rooms numeric;
  v_min_area numeric;
  v_furnished text;
  v_mode text;
  v_boroughs text[] := '{}'::text[];
  v_neighborhoods text[] := '{}'::text[];
  v_districts text[] := '{}'::text[];
begin
  select * into u
  from public.bot_users
  where id=p_user and is_active
  for share;
  if not found then raise exception 'participant_unavailable'; end if;

  if jsonb_typeof(p_values)<>'object' or octet_length(p_values::text)>24000 then
    raise exception 'invalid_profile';
  end if;

  slot:=coalesce((p_values->>'profile_slot')::integer,1);
  if slot<1 or slot>(case when app_private.user_is_premium(p_user) then 4 else 1 end) then
    raise exception 'profile_slot_not_allowed';
  end if;

  if coalesce(jsonb_typeof(p_values->'property_types'),'')<>'array'
     or jsonb_array_length(p_values->'property_types')<>1 then
    raise exception 'invalid_property_types';
  end if;
  v_type:=p_values#>>'{property_types,0}';
  if v_type not in ('Wohnung','Haus','WG','Tauschwohnung') then
    raise exception 'invalid_property_types';
  end if;
  types:=array[v_type];

  if (p_values->>'max_warm_rent') is null
     or (p_values->>'max_warm_rent')::numeric not between 100 and 5000 then
    raise exception 'invalid_profile_limits';
  end if;
  v_min_rooms:=(p_values->>'min_rooms')::numeric;
  v_min_area:=(p_values->>'min_area_sqm')::numeric;
  if v_min_rooms is null or v_min_rooms not between 1 and 20
     or v_min_area is null or v_min_area not between 0 and 1000 then
    raise exception 'invalid_profile_limits';
  end if;

  v_mode:=p_values->>'location_mode';
  if v_mode not in ('all_hamburg','boroughs','neighborhoods') or v_mode is null then
    raise exception 'invalid_profile_location';
  end if;

  if v_mode='boroughs' then
    if coalesce(jsonb_typeof(p_values->'boroughs'),'')<>'array'
       or jsonb_array_length(p_values->'boroughs')=0 then
      raise exception 'invalid_profile_location';
    end if;
    select coalesce(array_agg(value order by value),'{}'::text[])
      into v_boroughs
    from jsonb_array_elements_text(p_values->'boroughs') t(value);
    if (select count(*) from public.hamburg_boroughs where name=any(v_boroughs))<>cardinality(v_boroughs) then
      raise exception 'invalid_profile_location';
    end if;
    select coalesce(array_agg(hn.name order by hn.id),'{}'::text[])
      into v_districts
    from public.hamburg_neighborhoods hn
    join public.hamburg_boroughs hb on hb.id=hn.borough_id
    where hb.name=any(v_boroughs);
  elsif v_mode='neighborhoods' then
    if coalesce(jsonb_typeof(p_values->'neighborhoods'),'')<>'array'
       or jsonb_array_length(p_values->'neighborhoods')=0 then
      raise exception 'invalid_profile_location';
    end if;
    select coalesce(array_agg(value order by value),'{}'::text[])
      into v_neighborhoods
    from jsonb_array_elements_text(p_values->'neighborhoods') t(value);
    if (select count(*) from public.hamburg_neighborhoods where name=any(v_neighborhoods))<>cardinality(v_neighborhoods) then
      raise exception 'invalid_profile_location';
    end if;
    v_districts:=v_neighborhoods;
    select coalesce(array_agg(distinct hb.name order by hb.name),'{}'::text[])
      into v_boroughs
    from public.hamburg_neighborhoods hn
    join public.hamburg_boroughs hb on hb.id=hn.borough_id
    where hn.name=any(v_neighborhoods);
  else
    v_districts:=array['Ganz Hamburg']::text[];
  end if;

  select * into v
  from public.search_profiles
  where user_id=p_user and profile_slot=slot
  for update;

  v_furnished:=case
    when p_values?'furnished_preference' then
      case p_values->>'furnished_preference'
        when 'furnished' then 'yes'
        when 'unfurnished' then 'no'
        when 'yes' then 'yes'
        when 'no' then 'no'
        else 'any'
      end
    else coalesce(v.furnished_preference,'any')
  end;

  insert into public.search_profiles(
    user_id,profile_slot,name,property_types,location_mode,districts,boroughs,neighborhoods,
    max_warm_rent,min_rooms,min_area_sqm,min_room_area_sqm,wbs_only,furnished_preference,
    require_known_warm_rent,max_deposit,updated_at
  )
  values(
    p_user,slot,coalesce(v.name,case when slot=1 then 'Meine Suche' else 'Meine Suche '||slot end),
    types,v_mode,v_districts,v_boroughs,v_neighborhoods,
    (p_values->>'max_warm_rent')::numeric,v_min_rooms,v_min_area,0,
    case when p_values?'wbs_only' then (p_values->>'wbs_only')::boolean else coalesce(v.wbs_only,false) end,
    v_furnished,
    case when p_values?'require_known_warm_rent' then (p_values->>'require_known_warm_rent')::boolean else coalesce(v.require_known_warm_rent,false) end,
    case when p_values?'max_deposit' and nullif(p_values->>'max_deposit','') is not null
      then greatest(0,(p_values->>'max_deposit')::numeric) else v.max_deposit end,
    now()
  )
  on conflict(user_id,profile_slot) do update set
    property_types=excluded.property_types,
    location_mode=excluded.location_mode,
    districts=excluded.districts,
    boroughs=excluded.boroughs,
    neighborhoods=excluded.neighborhoods,
    max_warm_rent=excluded.max_warm_rent,
    min_rooms=excluded.min_rooms,
    min_area_sqm=excluded.min_area_sqm,
    min_room_area_sqm=excluded.min_room_area_sqm,
    wbs_only=excluded.wbs_only,
    furnished_preference=excluded.furnished_preference,
    require_known_warm_rent=excluded.require_known_warm_rent,
    max_deposit=excluded.max_deposit,
    updated_at=now()
  returning id into v_id;

  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION app_private.telegram_api_call(p_method text, p_body jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
