CREATE OR REPLACE FUNCTION app_private.validate_application_preferences()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists(select 1 from pg_catalog.pg_timezone_names where name=new.timezone) then
    raise exception 'invalid_timezone';
  end if;
  new.updated_at := now();
  if tg_op='UPDATE' and row(
    new.enabled,new.daily_limit,new.timezone,new.allowed_weekdays,
    new.send_window_start,new.send_window_end,
    new.immoscout_enabled,new.kleinanzeigen_enabled,new.immomio_enabled,new.immowelt_enabled
  ) is distinct from row(
    old.enabled,old.daily_limit,old.timezone,old.allowed_weekdays,
    old.send_window_start,old.send_window_end,
    old.immoscout_enabled,old.kleinanzeigen_enabled,old.immomio_enabled,old.immowelt_enabled
  ) then
    new.config_version := old.config_version + 1;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION graphql_public.graphql("operationName" text DEFAULT NULL::text, query text DEFAULT NULL::text, variables jsonb DEFAULT NULL::jsonb, extensions jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $function$
